from calendar import monthrange
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    first = date.fromisoformat(start)
    tokens = rule.split()
    frequency = tokens[0]
    interval = int(tokens[1])
    weekdays = {
        "MO": 0, "TU": 1, "WE": 2, "TH": 3,
        "FR": 4, "SA": 5, "SU": 6,
    }

    if frequency == "DAILY":
        return [
            (first + timedelta(days=i * interval)).isoformat()
            for i in range(count)
        ]

    if frequency == "WEEKLY":
        selected = sorted(weekdays[code] for code in tokens[2].split(","))
        monday = first - timedelta(days=first.weekday())
    elif frequency == "MONTHLY":
        base_month = first.year * 12 + first.month - 1
        requested = int(tokens[2])
        weekday = weekdays[tokens[3]] if len(tokens) == 4 else None
    else:
        month, day = map(int, tokens[2].split("-"))

    result = []
    period = 0

    while True:
        candidates = []

        if frequency == "WEEKLY":
            week_start = monday + timedelta(weeks=period * interval)
            candidates = [
                week_start + timedelta(days=weekday)
                for weekday in selected
            ]

        elif frequency == "MONTHLY":
            year, month_index = divmod(base_month + period * interval, 12)
            month = month_index + 1
            first_weekday, days_in_month = monthrange(year, month)

            if weekday is None:
                day = days_in_month if requested == -1 else requested
            elif requested == -1:
                last_weekday = (first_weekday + days_in_month - 1) % 7
                day = days_in_month - (last_weekday - weekday) % 7
            else:
                day = (
                    1 + (weekday - first_weekday) % 7
                    + 7 * (requested - 1)
                )

            if day <= days_in_month:
                candidates.append(date(year, month, day))

        else:  # YEARLY
            year = first.year + period * interval
            if day <= monthrange(year, month)[1]:
                candidates.append(date(year, month, day))

        for candidate in candidates:
            if candidate >= first:
                result.append(candidate.isoformat())
                if len(result) == count:
                    return result

        period += 1
